import{_ as l,l as t,o,c as r,v as a,p as i,x as d,d as n,i as s,S as C}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Claude Code","description":"","frontmatter":{"title":"Claude Code","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/claude-code-cli.md","filePath":"llm/claude-code-cli.md","lastUpdated":1789023840000}'),u={name:"llm/claude-code-cli.md"};function p(h,e,m,A,E,B){const c=t("Mermaid");return o(),r("div",null,[e[1]||(e[1]=a('<h1 id="claude-code" tabindex="-1">Claude Code <a class="header-anchor" href="#claude-code" aria-label="Permalink to &quot;Claude Code&quot;">​</a></h1><div class="epigraph"><p>在仓库里读文件、改文件、跑命令，并把 git、MCP 与项目说明书接进同一条智能体循环——终端只是这条循环最先露出的表面。</p><footer>—— Anthropic，Claude Code 官方文档 Overview 与 CLI reference（code.claude.com）</footer></div><p>Claude Code 是 Anthropic 的编程智能体产品：不是聊天框里贴一段补丁，而是带工具循环的代理，能在你的项目上计划、编辑、执行与提交。官方把它铺到终端 CLI、IDE 扩展、桌面应用与浏览器；底层是同一套引擎，所以 <code>CLAUDE.md</code>、设置与 MCP 服务器可以跨表面复用。本篇按官方文档写 CLI 合同与工作流组件，默认场景是开发者在自己的仓库里改功能与测试。不写越权扫描、攻击载荷或绕过权限的步骤。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>IDE 补全一次只动光标附近。Chat 窗口没有「仓库是工作区」的状态：模型看不见测试是否红、git 是否脏、上一步编辑是否可编译。把整个循环交给无审批的脚本，失败时又难以把责任钉到某一次工具调用。Claude Code 针对的是<strong>有工具、有项目记忆、可脚本化</strong>的代理：读代码库、跨文件编辑、跑命令、处理 git，并用自然语言当入口。</p><p>第二个问题是同一代理要出现在多种界面。若 CLI 与 VS Code 各搞一套提示与权限，团队无法把规范写进仓库。官方选择：多表面、单引擎。终端是完整 CLI；VS Code / Cursor / JetBrains 提供内联 diff 与对话；桌面端并排多会话与定时任务；Web 与手机负责不在本机仓库上的长任务。会话可以用 <code>--teleport</code>、<code>/desktop</code>、Remote Control 在表面之间搬，而不是复制粘贴上下文。</p><h3 id="unix-组合子-而不是只能交互" tabindex="-1">Unix 组合子，而不是只能交互 <a class="header-anchor" href="#unix-组合子-而不是只能交互" aria-label="Permalink to &quot;Unix 组合子，而不是只能交互&quot;">​</a></h3><p>官方强调可组合：把日志管道进 <code>claude -p</code>，在 CI 里翻译字符串并开 PR，或把 <code>git diff</code> 的文件列表交给它做审查。<code>-p</code> 走 SDK 查询然后退出；<code>-c</code> 继续当前目录最近一次对话；<code>-r</code> 按会话 ID 或名字恢复。这把代理从「一个 TUI」变成可以嵌进 make / GitHub Actions 的过滤器。交互模式仍是日常主路径，无头模式是同一循环的批处理接口。</p><p><span class="marginnote">安装以官方文档为准：macOS/Linux 推荐 <code>curl</code> 安装脚本，也可用 Homebrew cask；Windows 用 PowerShell 脚本或 WinGet。npm 全局包已弃用。Homebrew / WinGet 不自动升级，需手动 <code>upgrade</code>。原生安装会在后台更新。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在项目目录运行 <code>claude</code>，首次登录 Claude 订阅或 Anthropic Console；若已设 <code>ANTHROPIC_API_KEY</code>，则跳过登录、改为确认密钥。终端、VS Code 与 JetBrains 还支持第三方模型提供方。典型任务：为模块补测试并修到绿、按症状追 bug、写提交说明与开 PR。CI 里可用 GitHub Actions 或 GitLab CI 做自动审查与 issue 分流。</p><p>项目说明书是 <code>CLAUDE.md</code>：放在仓库根，每次会话开始时读取，用来写编码规范、架构决策、首选库与审查清单。Claude 还会在工作中积累自动记忆。可复用流程打成 <strong>Skills</strong>（例如 <code>/review-pr</code>）；<strong>Hooks</strong> 在编辑前后跑 shell——官方例子是编辑后格式化、提交前 lint。MCP 把 Drive、Jira、Slack 或自建工具接进来。需要并行时，主代理可派生子代理，或用后台代理并排跑多个完整会话。完全自定义的编排走 Agent SDK，而不是在 CLI 里重写循环。</p>',12)),(o(),i(C,null,{default:d(()=>[s(c,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E8%87%AA%E7%84%B6%E8%AF%AD%E8%A8%80%E4%BB%BB%E5%8A%A1%22%5D%20--%3E%20L%5B%22%E5%8A%A0%E8%BD%BD%20CLAUDE.md%20%2F%20skills%20%2F%20MCP%22%5D%0A%20%20L%20--%3E%20P%5B%22%E8%AE%A1%E5%88%92%E4%B8%8E%E5%B7%A5%E5%85%B7%E5%BE%AA%E7%8E%AF%22%5D%0A%20%20P%20--%3E%20R%5B%22%E8%AF%BB%E6%96%87%E4%BB%B6%20%2F%20%E7%BC%96%E8%BE%91%20%2F%20%E8%B7%91%E5%91%BD%E4%BB%A4%22%5D%0A%20%20R%20--%3E%20H%5B%22Hooks%EF%BC%9A%E6%A0%BC%E5%BC%8F%E5%8C%96%C2%B7lint%22%5D%0A%20%20H%20--%3E%20G%5B%22git%EF%BC%9A%E6%8F%90%E4%BA%A4%20%2F%20PR%22%5D%0A%20%20P%20--%3E%20S%5B%22%E5%AD%90%E4%BB%A3%E7%90%86%E5%B9%B6%E8%A1%8C%22%5D%0A%20%20S%20--%3E%20P%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h3 id="cli-作为自动化接口" tabindex="-1">CLI 作为自动化接口 <a class="header-anchor" href="#cli-作为自动化接口" aria-label="Permalink to &quot;CLI 作为自动化接口&quot;">​</a></h3><p>CLI reference 把「开会话、管道、恢复、更新」收成命令表。<code>claude &quot;query&quot;</code> 带初始提示进入交互；<code>cat file | claude -p &quot;query&quot;</code> 处理管道内容；<code>claude -c -p</code> 在无头续写。<code>--output-format json</code> 方便脚本解析。<code>claude mcp</code> 管理 MCP 服务器。企业侧另有 <code>claude gateway</code>，在 Bedrock 或 Google Cloud Agent Platform 前加 SSO 与策略（需配置文件，版本门槛以文档为准）。<code>claude --help</code> 列不全所有开关：缺席不等于不存在，完整列表看 CLI reference。</p><p>官方工作流还包括例行任务：云端 Routines（机器关机仍跑，可被 API 或 GitHub 事件触发）、桌面定时任务（碰得到本机文件）、会话内 <code>/loop</code> 轮询。这些是产品能力，不是把代理暴露成对任意主机的巡检器；权限与网络范围仍由设置与用户批准约束。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>循环与 <a href="/llm/react-prompting">ReAct</a> 同类：模型在「读—改—跑—观察」里更新信念，直到判定完成或要人。<code>CLAUDE.md</code> 把团队规范从对话里搬到文件系统，使每次会话的先验相同。Skills 按需加载程序知识，避免把全部手册塞进系统提示。Hooks 把确定性步骤（格式化、lint）固定在工具生命周期上，减少「模型忘记跑 formatter」的方差。MCP 把外部系统变成工具表上的名字，而不是让模型去猜 HTTP。</p><p>git 是状态外置：提交与 PR 让代理的工作可审查、可回退，失败不必依赖会话记忆。管道与 <code>-p</code> 把同一循环接到非 TTY，使 CI 与本地共用提示词。多表面共享引擎，则是把「规范写在仓库里」变成可执行的：手机上续做的任务仍受同一套 <code>CLAUDE.md</code> 约束。</p><p><span class="marginnote">JetBrains 插件依赖单独安装的 CLI。Web 与桌面的云会话碰不到你的 <code>~/.claude</code> 本机技能目录，只加载账户里启用的技能与仓库内 <code>.claude/skills/</code>。写部署时要声明技能从哪一层文件系统来。</span></p><h3 id="权限模型是产品-不是事后补丁" tabindex="-1">权限模型是产品，不是事后补丁 <a class="header-anchor" href="#权限模型是产品-不是事后补丁" aria-label="Permalink to &quot;权限模型是产品，不是事后补丁&quot;">​</a></h3><p>工具能跑任意命令，默认就有真实破坏半径。官方把确认、计划模式、允许列表与 MCP 作用域当作一等配置，而不是「先 YOLO 再后悔」。本篇只指出合同：敏感操作应保持人在环；企业用 gateway 与策略文件收口提供方。不要把文档里的自动化例子理解成关闭审批的许可。第三方登录与额度不得被未批准的产品拿去转售——这条在 Agent SDK 文档里写得更硬，CLI 集成同样适用。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>Claude Code 是产品，版本与开关会变；复现质量必须写文档日期与 <code>claude</code> 版本。npm 安装路径已弃用，教程若还写 <code>npm i -g @anthropic-ai/claude-code</code>，以官网为准。Homebrew 的 <code>claude-code</code> 跟踪稳定通道（大约落后一周、跳过严重回退），<code>claude-code@latest</code> 跟踪最新通道，两者升级策略不同。</p><p>相对 <a href="/llm/aider">Aider</a>：Aider 更窄、git 提交节奏更硬、编辑格式是一等公民；Claude Code 工具面更宽（MCP、子代理、多表面）。相对 Codex CLI / Gemini CLI：三者都是终端代理，但脚手架、权限默认、项目说明书文件名与开源许可都不同，基准数字不可互换。Agent SDK 把同一循环嵌进你的进程；只想交互时用 CLI，不要为了「可编程」强行解析 TUI。</p><p><span class="marginnote">出处：Anthropic，Claude Code Overview、CLI reference、Skills / Hooks / MCP 文档，<a href="https://code.claude.com/docs" target="_blank" rel="noreferrer">https://code.claude.com/docs</a> 。安装与故障排除以 Setup 页为准。本篇不引用第三方「命令大全」作为规范。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Claude Code 是带工具循环的编程代理，终端、IDE、桌面与 Web 共用引擎。</li><li>项目合同写在 <code>CLAUDE.md</code>；Skills、Hooks、MCP 分别提供流程、确定性钩子与外部工具。</li><li>CLI 的 <code>-p</code> / 管道 / JSON 输出把它变成 Unix 组合子；<code>-c</code> / <code>-r</code> 恢复会话。</li><li>多表面搬迁靠官方传送与 Remote Control，不是复制聊天记录。</li><li>默认在自有仓库、人在环；权限与企业网关是合同的一部分。</li><li>出处：code.claude.com 官方文档。</li></ul>',15))])}const _=l(u,[["render",p]]);export{f as __pageData,_ as default};
